class Solution {
    public long getMaxFunctionValue(List<Integer> receiver, long k) {
        int n = receiver.size();
        int m = 64 - Long.numberOfLeadingZeros(k);
        int[][] up = new int[n][m];
        long[][] sm = new long[n][m];
        for (int i = 0; i < n; i++) {
            up[i][0] = receiver.get(i);
            sm[i][0] = receiver.get(i);
        }
        for (int j = 1; j < m; j++) {
            for (int i = 0; i < n; i++) {
                int p = up[i][j - 1];
                up[i][j] = up[p][j - 1];
                sm[i][j] = sm[i][j - 1] + sm[p][j - 1];
            }
        }
        long ans = 0;
        for (int i = 0; i < n; i++) {
            int curr = i;
            long total = i;
            for (int j = 0; j < m; j++) {
                if (((k >> j) & 1) == 1) {
                    total += sm[curr][j];
                    curr = up[curr][j];
                }
            }
            ans = Math.max(ans, total);
        }
        return ans;
    }
}

/**
 * @param {number[]} receiver
 * @param {number} k
 * @return {number}
 */
var getMaxFunctionValue = function(receiver, k) {
    const n = receiver.length;
    const bk = BigInt(k);
    let m = 0;
    while ((1n << BigInt(m)) <= bk) m++;
    const up = Array.from({ length: n }, () => new Int32Array(m));
    const sm = Array.from({ length: n }, () => new BigInt64Array(m));
    for (let i = 0; i < n; i++) {
        up[i][0] = receiver[i];
        sm[i][0] = BigInt(receiver[i]);
    }
    for (let j = 1; j < m; j++) {
        for (let i = 0; i < n; i++) {
            const p = up[i][j - 1];
            up[i][j] = up[p][j - 1];
            sm[i][j] = sm[i][j - 1] + sm[p][j - 1];
        }
    }
    let ans = 0n;
    for (let i = 0; i < n; i++) {
        let curr = i;
        let total = BigInt(i);
        for (let j = 0; j < m; j++) {
            if ((bk >> BigInt(j)) & 1n) {
                total += sm[curr][j];
                curr = up[curr][j];
            }
        }
        if (total > ans) ans = total;
    }
    return Number(ans);
};
